<?php

declare(strict_types=1);

namespace Modules\Inventory\Http\Requests;

use Illuminate\Contracts\Validation\Validator;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
use Modules\Inventory\Enums\ReturnReason;

/**
 * Header + lines of a supplier return. return_no is never accepted — it is generated by
 * SupplierReturnService. Returnable quantities, roll stock and the GRN date are checked
 * against the live GRN in the service, not here.
 */
class StoreSupplierReturnRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    /** @return array<string, array<int, mixed>> */
    public function rules(): array
    {
        return [
            'return_date' => ['required', 'date', 'before_or_equal:today'],
            'supplier_id' => ['required', 'integer', 'exists:inv_supplier_masters,id'],
            'grn_id'      => ['required', 'integer', 'exists:inv_goods_received_notes,id'],
            'store_id'    => ['required', 'integer', 'exists:inv_stores,id'],
            'remarks'     => ['nullable', 'string', 'max:1000'],

            'items'               => ['required', 'array', 'min:1'],
            'items.*.grn_item_id' => ['required', 'integer', 'distinct'],
            // Quantity lines carry a quantity; roll lines carry per-roll quantities instead.
            'items.*.quantity'    => ['nullable', 'numeric', 'min:0', 'max:99999999999'],
            'items.*.reason'      => ['required', Rule::enum(ReturnReason::class)],
            'items.*.remarks'     => ['nullable', 'string', 'max:500'],

            'items.*.pieces'            => ['nullable', 'array'],
            'items.*.pieces.*.piece_id' => ['required_with:items.*.pieces', 'integer', 'distinct'],
            'items.*.pieces.*.quantity' => ['required_with:items.*.pieces', 'numeric', 'gt:0', 'max:99999999999'],
        ];
    }

    /** @return array<string, string> */
    public function attributes(): array
    {
        return [
            'supplier_id'               => 'supplier',
            'grn_id'                    => 'GRN',
            'store_id'                  => 'return store',
            'items.*.grn_item_id'       => 'GRN line',
            'items.*.quantity'          => 'return quantity',
            'items.*.reason'            => 'reason',
            'items.*.pieces.*.piece_id' => 'roll',
            'items.*.pieces.*.quantity' => 'roll return quantity',
        ];
    }

    /** @return array<string, string> */
    public function messages(): array
    {
        return [
            'return_date.before_or_equal' => 'The return date cannot be in the future.',
            'items.required'              => 'Select at least one line to return.',
            'items.min'                   => 'Select at least one line to return.',
        ];
    }

    public function withValidator(Validator $validator): void
    {
        $validator->after(function (Validator $validator): void {
            foreach ((array) $this->input('items', []) as $index => $item) {
                $hasPieces = !empty($item['pieces']);
                $quantity  = (float) ($item['quantity'] ?? 0);

                if (!$hasPieces && $quantity <= 0) {
                    $validator->errors()->add("items.{$index}.quantity", 'Enter the quantity being returned.');
                }
            }
        });
    }
}
